int main() {
    int total;
    if (!(std::cin >> total)) { std::cout << "invalid\n"; return 0; }
    if (total < 0) { std::cout << "invalid\n"; return 0; }
    if (total >= 1000) std::cout << "free\n";
    else std::cout << "150\n";
}

#include <iostream>
int main() {
    int score;
    if (!(std::cin >> score)) { std::cout << "invalid\n"; return 0; }
    if (score < 0 || score > 100) std::cout << "invalid\n";
    else if (score >= 60) std::cout << "pass\n";
    else std::cout << "retry\n";
}

laboratory.referenceCode:
#include <iostream>
int main() {
    int distance;
    if (!(std::cin >> distance)) { std::cout << "invalid\n"; return 0; }
    if (distance <= 0 || distance > 1000000) { std::cout << "invalid\n"; return 0; }
    int cost = 100;
    if (distance > 5) cost += (distance - 5) * 20;
    std::cout << cost << '\n';
}

